    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    colors = sorted({grid[r][c] for r, c in cells})
    cmap = {0: 0, colors[0]: colors[1], colors[1]: colors[0]}
    brush = [[cmap[grid[r][c]] for c in range(c0, c1 + 1)]
             for r in range(r0, r1 + 1)]
    bh, bw = len(brush), len(brush[0])

    cells = [(r, c) for r in groups[1] for c in range(sep) if grid[r][c]]
    gr0, gr1 = min(r for r, c in cells), max(r for r, c in cells)
    gc0, gc1 = min(c for r, c in cells), max(c for r, c in cells)
    guide = [[1 if grid[r][c] else 0 for c in range(gc0, gc1 + 1)]
             for r in range(gr0, gr1 + 1)]

    marker = next((r, c) for r in range(split + 1, h) for c in range(sep)
                  if grid[r][c] == 4)
    interior = [(r, c) for r in range(split + 1, h) for c in range(sep)
                if grid[r][c] == 0]
    top, left = min(r for r, c in interior), min(c for r, c in interior)
    corner = (marker[0] - top, marker[1] - left)

    # The yellow corner marker rotates the placement plan; the stamp itself
    # keeps its orientation.
    if corner == (0, 0):
        pass
    elif corner == (0, 2):
        guide = [list(row) for row in zip(*guide[::-1])]
    elif corner == (2, 2):
        guide = [list(reversed(row)) for row in guide[::-1]]
    else:
